contract InvMutTest {
    C c;
    constructor() { c = new C(address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address sender) public payable {
        // require that the caller passed as `sender` is the owner according to c
        // We cannot read owner directly (it is public so we can), so require msg.sender match is not applicable.
        // Instead, we ensure caller of withdrawAll is the owner by making this contract act as that owner:
        // The only observable that determines revert in the original is whether msg.sender == owner.
        // So we require that this contract is the owner by checking c.owner() == address(this).
        require(c.owner() == address(this));

        bool reverted;
        c.withdrawAll(sender); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        // General rule: when called by the owner, withdrawAll should not revert.
        assert(reverted == false);
    }
    receive() external payable { }
}

